import requests

def charge(order, gateway_url):
    payload = {'amount': order.amount_paise, 'currency': 'INR', 'customer_id': order.customer_id}
    headers = {'Idempotency-Key': str(order.payment_attempt_id)}
    for attempt in range(3):
        try:
            response = requests.post(gateway_url + '/charges', json=payload, headers=headers, timeout=5)
            response.raise_for_status()
            return response.json()
        except requests.Timeout:
            if attempt == 2:
                raise

import hashlib
import hmac
import json

def handle_payment_event(request, orders, webhook_secret):
    signature = request.headers.get('X-Payment-Signature', '')
    expected = hmac.new(webhook_secret.encode(), request.body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise PermissionError('Invalid webhook signature')
    event = json.loads(request.body)
    if event['type'] == 'payment.captured':
        orders.mark_paid_once(event['id'], event['data']['order_id'])
    return {'status': 'accepted'}

