def get_invoice(db, authenticated_user, invoice_id):
    row = db.execute(
        'SELECT id, amount, customer_email FROM invoices WHERE id = ?',
        (invoice_id,),
    ).fetchone()
    if row is None:
        raise LookupError('Invoice not found')
    return dict(row)

